  if(a[0]==='Za granicą'&&steps[1])Object.assign(steps[1],{name:'Po rejestracji zagranicznego aktu sprawdź PESEL dziecka',detail:'Po uzyskaniu polskiego aktu lub wpisu zagranicznego aktu sprawdź, czy dziecko ma już PESEL. Procedura i wymagane dokumenty zależą od kraju wydania aktu.',why:'Rejestracja zagranicznego aktu i uzyskanie polskich danych mogą wymagać dodatkowego kroku w USC.',docs:['Zagraniczny akt urodzenia','Dokument z USC potwierdzający rejestrację, jeśli został wydany'],deadline:'Termin potwierdź w USC prowadzącym sprawę.',where:'USC lub właściwy konsulat.',url:'https://www.gov.pl/web/gov/uzyskaj-odpis-aktu-stanu-cywilnego'});
